/** Answer statuses at 400 or above, by route (generated client). */
export const ANSWER_STATUSES: Readonly<Record<string, readonly number[]>> = {
  "collaboration.revision-requests.post": [200,409],
  "live.document.put": [200,409],
};

export const SHARED_ERRORS = {"401":["session_idle_expired"],"429":["too_many_requests"],"500":["internal"]} as const;

type Input<Id extends OperationId> = Pick<Operations[Id], "params" | "query" | "body">;
export type Result<Id extends OperationId> =
  | (Operations[Id]["success"] & { ok: true })
  | { ok: false; status: number; code: Operations[Id]["errorCode"] | SharedErrorCode | "unexpected" };

/**
 * The RFC 8785 (JCS) text of a JSON value: object keys in UTF-16 code unit
 * order, no white space, numbers and strings as JSON.stringify writes them.
 * Routes that read canonical JSON (support.problem-report.post) refuse any
 * other spelling with 422, so every JSON body is sent this way.
 */
const LONE_SURROGATE = /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/;

export function canonicalJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map((item) => canonicalJson(item === undefined ? null : item)).join(",")}]`;
  if (value !== null && typeof value === "object") {
    const record = value as Record<string, unknown>;
    const keys = Object.keys(record).sort().filter((key) => record[key] !== undefined);
    for (const key of keys) canonicalJson(key);
    return `{${keys.map((key) => `${JSON.stringify(key)}:${canonicalJson(record[key])}`).join(",")}}`;
  }
  // JCS refuses a lone surrogate (RFC 8785 §3.2.2.2), as Ductus canonicalizeJcs does.
  if (typeof value === "string" && LONE_SURROGATE.test(value)) throw new TypeError("canonicalJson: lone surrogate");
  return JSON.stringify(value) ?? "null";
}

export function createClient(baseUrl: string, fetchImpl: typeof fetch = fetch) {
  return async function call<Id extends OperationId>(id: Id, input: Input<Id>): Promise<Result<Id>> {
    const route = ROUTE_TABLE[id];
    const params = (input.params ?? {}) as Record<string, string>;
    let path: string = route.path.replace(/\{(\w+)\}/g, (match, name: string) => encodeURIComponent(params[name] ?? ""));
    const query = new URLSearchParams(
      Object.entries((input.query ?? {}) as Record<string, string | undefined>).filter((e): e is [string, string] => e[1] !== undefined),
    );
    if (query.size > 0) path += `?${query.toString()}`;
    const init: RequestInit = { method: route.method, redirect: "manual" };
    if (route.body === "application/json") init.body = canonicalJson(input.body);
    if (route.body === "application/x-www-form-urlencoded") init.body = new URLSearchParams(input.body as Record<string, string>).toString();
    // A multipart body: fetch writes the content type with its boundary itself.
    if (route.body === "multipart/form-data") {
      const form = new FormData();
      for (const [name, value] of Object.entries(input.body as Record<string, string | Blob | undefined>)) {
        if (value !== undefined) form.append(name, value);
      }
      init.body = form;
    } else if (route.body !== null) init.headers = { "content-type": route.body };
    const res = await fetchImpl(new URL(path, baseUrl), init);
    // In a browser a manual redirect is opaque (status 0); every contracted redirect is a 303.
    if (res.type === "opaqueredirect") return { ok: true, status: 303, body: undefined, headers: {} } as Result<Id>;
    const type = res.headers.get("content-type") ?? "";
    // A binary answer (image/jpeg, DOCX) is read as a Blob; it is never a problem body.
    const body: unknown = type.startsWith("application/json") ? await res.json() : (type.startsWith("image/") || type.startsWith("text/csv") || type.startsWith("application/vnd.openxmlformats-officedocument.")) && res.status < 400 ? await res.blob() : undefined;
    // A status the contract lists as an answer is one even at 400 or above
    // (live.document.put 409 {outcome, token}), unless its body is a problem
    // body: the same status can also be an error (revision-requests 409).
    // Only a JSON body that is not a problem body (no error, no code) is an answer.
    const answer = typeof body === "object" && body !== null && !("error" in body) && !("code" in body);
    if (res.status < 400 || ((ANSWER_STATUSES[id] ?? []).includes(res.status) && answer)) {
      // The headers the contract says callers rely on (location, set-cookie), nothing else.
      const headers: Record<string, string | string[]> = {};
      for (const name of route.headers as readonly string[]) {
        const value = name === "set-cookie" ? res.headers.getSetCookie() : res.headers.get(name);
        if (value !== null && value.length > 0) headers[name] = value;
      }
      return { ok: true, status: res.status, body, headers } as Result<Id>;
    }
    const known = (route.errors as Record<number, readonly string[] | undefined>)[res.status] ?? [];
    // The code is in "code" (problem body, S-1L.3); a v1 body without it has it in "error",
    // and readiness and evidence in "status" ({status: "draining"}).
    const fields = body && typeof body === "object" ? (body as { code?: unknown; error?: unknown; status?: unknown }) : {};
    const sent = [fields.code, fields.error, fields.status].find((value) => typeof value === "string");
    // A body without a code takes the only code of its status; an unknown code is never renamed.
    // A shared code (500 internal) counts only when the body names it, never for a bare status.
    const shared = (SHARED_ERRORS as Record<number, readonly string[] | undefined>)[res.status] ?? [];
    const code = typeof sent === "string" ? (known.includes(sent) || shared.includes(sent) ? sent : "unexpected") : known.length === 1 ? known[0] : "unexpected";
    return { ok: false, status: res.status, code } as Result<Id>;
  };
}
